-- gap andor:384:22:1, written by an automated writer
test("breakit Net.Rides: driver acceptance cannot charge a raincheck rider above the requested fare", function()
	local w = T.newWorld()
	local bot = w:addBot(T.BOB, { spot = "Ratchet", class = "WARLOCK" })
	local r = T.rider(w, T.TESTCHAR, { spot = "Orgrimmar" })
	T.settle(w)
	w:inject(T.BOB, "D~1~Ratchet~1413~627~370~10000~Bob Stone~open~1~4~H~2.3.0", "CHANNEL")
	local t = r.env.time()
	r.W.db.rainchecks = { Rc000001 = { driverKey = "bob stone", driver = T.BOB, service = "Bob Stone",
		cover = 2000, expires = t + 86400, state = "active", rideId = "QQQQQQ", at = t } }
	local ride = r.W.RequestRide("bob stone")
	ok(ride, "ride requested")
	w:inject(T.BOB, "A~1~" .. ride.id .. "~20000~0~1", "WHISPER", r)
	w:group({ T.BOB, T.TESTCHAR })
	w:move(T.TESTCHAR, "Ratchet")
	w:advance(0.5)
	ok(w:openTrade(r, bot), "trade opens with driver")
	w:tradeMoney(r, 8000)
	w:tradeAccept(r)
	w:tradeAccept(bot)
	w:advance(1)
	eq(r.env.WuberDB.ride.state, "done", "paying the capped 80s completes the ride")
	eq(#r.env.WuberDB.rides, 1, "completed ride is saved in trips")
	eq(r.env.WuberDB.rides[1].price, 8000, "saved trip records 80s after raincheck cover")
	T.clean(w)
end)

