-- gap drop:270:17:1, written by an automated writer
test("breakit Net.Rides: rating a finished ride saves the star rating on the recorded trip", function()
	local function hasTable(tbl, target, seen)
		if tbl == target then return true end
		if type(tbl) ~= "table" or seen[tbl] then return false end
		seen[tbl] = true
		for k, v in pairs(tbl) do
			if hasTable(v, target, seen) then return true end
		end
		return false
	end
	local w = T.newWorld()
	local d = w:addBot(T.ANITA, { spot = "Orgrimmar", class = "WARLOCK" })
	local r = T.rider(w, T.TESTCHAR)
	T.settle(w)
	w:inject(T.ANITA, "D~1~Ratchet~1413~500~500~5000~~open~1~0~~2.3.1", "CHANNEL")
	w:advance(0.2)
	local ride = r.W.RequestRide("anita lift")
	ok(ride, "ride requested")
	w:group({ T.ANITA, T.TESTCHAR })
	ride.state = "arrived"
	ok(w:openTrade(d, r), "trade opened with driver")
	w:tradeMoney(r, 5000)
	w:tradeAccept(d)
	w:tradeAccept(r)
	w:advance(3)
	if not ride.trip then r.W.EndRide() end
	ok(r.W.Rate(4), "rating accepted")
	local trip = r.W.ride.trip
	ok(trip ~= nil, "ride has a trip record")
	ok(hasTable(r.env.WuberDB, trip, {}), "trip record is stored in saved variables")
	eq(trip.stars, 4, "trip record stores the chosen star rating")
	T.clean(w)
end)

